} ]
}, {
  "tStartMs": 839839,
  "dDurationMs": 1434,
  "segs": [ {
    "utf8": "那我那時候在講文化徑的時候"
  } ]
}, {
  "tStartMs": 841273,
  "dDurationMs": 768,
  "segs": [ {
    "utf8": " 我就覺得"
  } ]
}, {
  "tStartMs": 842041,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "當然我們可以講得比較中性一點"
  } ]
}, {
  "tStartMs": 844143,
  "dDurationMs": 2402,
  "segs": [ {

text:
    "utf8": "比如說我們就講茶跟礦的歷史"
  } ]
}, {
  "tStartMs": 846545,
  "dDurationMs": 2503,
  "segs": [ {
    "utf8": "這個在清朝在日治其實都有"
  } ]
}, {
  "tStartMs": 849048,
  "dDurationMs": 1935,
  "segs": [ {
    "utf8": "或者我們去講一些 "
  } ]
}, {
  "tStartMs": 850983,
  "dDurationMs": 1652,
  "segs": [ {
    "utf8": "這個城市的記憶"
  } ]
}, {
  "tStartMs": 852635,
  "dDurationMs": 1801,
  "segs": [ {
    "utf8": "就是說比如說我們講近代一點"
  } ]
}, {
  "tStartMs": 854436,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "比如說光華商場"
  } ]
}, {
  "tStartMs": 855437,
  "dDurationMs": 2286,
  "segs": [ {
    "utf8": "是我的很重要的記憶"
  } ]
}, {
  "tStartMs": 857723,
  "dDurationMs": 1935,
  "segs": [ {
    "utf8": "但是我就覺得在往前的那個歷史"
  } ]
}, {
  "tStartMs": 859658,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "很多是沒有被連接起來"
  } ]
}, {
  "tStartMs": 861360,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "所以我那時候才會講說"
  } ]
}, {
  "tStartMs": 862761,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "我們的多元族群的歷史"
  } ]
}, {
  "tStartMs": 864463,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "還有我們人權相關的"
  } ]
}, {
  "tStartMs": 866465,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "這四個就是我剛剛講的 "
  } ]
}, {
  "tStartMs": 867867,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "這四個城市記憶"
  } ]
}, {
  "tStartMs": 869368,
  "dDurationMs": 5506,
  "segs": [ {
    "utf8": "人權還有這個產業 "
  } ]
}, {
  "tStartMs": 874874,
  "dDurationMs": 1918,
  "segs": [ {
    "utf8": "然後這幾個全部加起來"
  } ]
}, {
  "tStartMs": 876792,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "都應該在我們的文化徑裡面"
  } ]
}, {
  "tStartMs": 878694,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "我覺得這應該都被重視"
  } ]
}, {
  "tStartMs": 880496,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "那我之前也很常講"
  } ]
}, {
  "tStartMs": 881697,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "甚至我們講客家 就是說"
  } ]
}, {
  "tStartMs": 883499,
  "dDurationMs": 1768,
  "segs": [ {
    "utf8": "因為以前就是浪漫台三線"
  } ]
}, {
  "tStartMs": 885267,
  "dDurationMs": 1135,
  "segs": [ {
    "utf8": " 很常被提到"
  } ]
}, {
  "tStartMs": 886402,
  "dDurationMs": 1451,
  "segs": [ {
    "utf8": "我也參與過好幾次 "
  } ]
}, {
  "tStartMs": 887853,
  "dDurationMs": 1552,
  "segs": [ {
    "utf8": "客家庄會連在一起"
  } ]
}, {
  "tStartMs": 889405,
  "dDurationMs": 800,
  "segs": [ {
    "utf8": "然後我就覺得說"
  } ]
}, {
  "tStartMs": 890205,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "可是台三線起點在台北"
  } ]
}, {
  "tStartMs": 891690,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": "然後台北又有五六十萬的客家人"
  } ]
}, {
  "tStartMs": 894093,
  "dDurationMs": 1701,
  "segs": [ {
    "utf8": "那我們台北怎麼沒有加入"
  } ]
}, {
  "tStartMs": 895794,
  "dDurationMs": 801,
  "segs": [ {
    "utf8": "真的"
  } ]
}, {
  "tStartMs": 896595,
  "dDurationMs": 868,
  "segs": [ {
    "utf8": "我就覺得說就是 "
  } ]
}, {
  "tStartMs": 897463,
  "dDurationMs": 1435,
  "segs": [ {
    "utf8": "我們很明顯的對於"
  } ]
}, {
  "tStartMs": 898898,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "每一個族群的歷史的重視"
  } ]
}, {
  "tStartMs": 901000,
  "dDurationMs": 1318,
  "segs": [ {
    "utf8": "還有像我們剛剛提到的 "
  } ]
}, {
  "tStartMs": 902318,
  "dDurationMs": 1284,
  "segs": [ {
    "utf8": "台南很多人"
  } ]
}, {
  "tStartMs": 903602,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "嘉義很多人"
  } ]
}, {
  "tStartMs": 904703,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "雲林也很多人"
  } ]
}, {
  "tStartMs": 905804,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "他們都是來台北打拚"
  } ]
}, {
  "tStartMs": 907289,
  "dDurationMs": 1302,
  "segs": [ {
    "utf8": "然後變成了台北人"
  } ]
}, {
  "tStartMs": 908591,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "那他們的足跡 "
  } ]
}, {
  "tStartMs": 909892,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "他們的歷史"
  } ]
}, {
  "tStartMs": 911093,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "光是一個進站的音樂"
  } ]
}, {
  "tStartMs": 912595,
  "dDurationMs": 1701,
  "segs": [ {
    "utf8": "就可以開始講他們的歷史"
  } ]
}, {
  "tStartMs": 914296,
  "dDurationMs": 801,
  "segs": [ {
    "utf8": "你講到這一點"
  } ]
}, {
  "tStartMs": 915097,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "我就特別想到"
  } ]
}, {
  "tStartMs": 916198,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "像台三線或者台一線也好"
  } ]
}, {
  "tStartMs": 918400,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "剛好我今年自己有個計畫"
  } ]
}, {
  "tStartMs": 920302,
  "dDurationMs": 1535,
  "segs": [ {
    "utf8": "是在走日本的東海道"
  } ]
}, {
  "tStartMs": 921837,
  "dDurationMs": 1869,
  "segs": [ {
    "utf8": "就是從東京的日本橋"
  } ]
}, {
  "tStartMs": 923706,
  "dDurationMs": 3486,
  "segs": [ {
    "utf8": "然後要一直走到京都三條大橋"
  } ]
}, {
  "tStartMs": 927192,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "當然我分了好幾個月"
  } ]
}, {
  "tStartMs": 928794,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "對 這個很強"
  } ]
}, {
  "tStartMs": 930296,
  "dDurationMs": 1801,
  "segs": [ {
    "utf8": "一次走完就很長五百公里"
  } ]
}, {
  "tStartMs": 932097,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "可是我在走那個過程當中"
  } ]
}, {
  "tStartMs": 933999,
  "dDurationMs": 1302,
  "segs": [ {
    "utf8": "我就是發現到說"
  } ]
}, {
  "tStartMs": 935301,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "對 它就是在記錄以前的人"
  } ]
}, {
  "tStartMs": 937703,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "是如何從地方"
  } ]
}, {
  "tStartMs": 939705,
  "dDurationMs": 2085,
  "segs": [ {
    "utf8": "然後走到當時的江戶"
  } ]
}, {
